    TestCase.assertTrue(em.getMappings().isEmpty());
    TestCase.assertTrue(em.getHttpContexts().isEmpty());
    TestCase.assertEquals(0, this.httpService.getServlets().size());
    TestCase.assertTrue(em.getOrphanMappings().isEmpty());
}

