@Test
public void test_concurrent_deactivation() throws Exception {
    final Bundle bundle1 = installBundle("/integration_test_FELIX_4188_1.xml", "", "simplecomponent1");
    bundle1.start();
    final Bundle bundle2 = installBundle("/integration_test_FELIX_4188_2.xml", "", "simplecomponent2");
    bundle2.start();
    final Component aComp1 = findComponentByName("org.apache.felix.scr.integration.components.Felix4188Component-1");
    aComp1.enable();
    final Object aInst1 = aComp1.getComponentInstance().getInstance();
    final Component aComp2 = findComponentByName("org.apache.felix.scr.integration.components.Felix4188Component-2");
    aComp2.enable();
    final Object aInst2 = aComp2.getComponentInstance().getInstance();
    final CountDownLatch latch = new CountDownLatch(1);
    new Thread() {

        public void run() {
            Bundle scrBundle = scrTracker.getServiceReference().getBundle();
            try {
                scrBundle.stop();
            } catch (Throwable t) {
                t.printStackTrace();
            } finally {
                latch.countDown();
            }
        }
    }.start();
    Thread.sleep(100);
    long t0 = System.currentTimeMillis();
    bundle1.stop();
    bundle2.stop();
    long t1 = System.currentTimeMillis();
    // It should have taken more than a second
    TestCase.assertTrue(t1 - t0 > 1000);
    TestCase.assertNull(getField(aInst1, "throwable"));
    TestCase.assertNull(getField(aInst2, "throwable"));
    latch.await();
    TestCase.assertNull(getField(aInst1, "throwable"));
    TestCase.assertNull(getField(aInst2, "throwable"));
}

